    date: string;
    description: string;
    metrics?: { label: string; value: string }[];
    skills: string[];
}

interface Project {
    title: string;
    category: string;
    role: string;
    description: string;
    tech: string;
    link?: string;
}

const experiences: Experience[] = [
    {
        company: "Blue Oak Group",
        role: "PE Summer Analyst",
        date: "May 2026 – present",
        description: "Built an AI acquisition-sourcing / broker-scraper workflow. Worked on real PE deals (Foss Enterprises, Union Door). Sponsor: Coleman Kraemer.",
        skills: ["AI/ML", "Sourcing", "PE Deals"]
