1	'use client';
2	
3	import { motion, AnimatePresence } from 'framer-motion';
4	import { useTourController } from './useTourController';
5	import { useState, useRef, useCallback } from 'react';
6	import { Play, Pause, SkipBack, SkipForward, X, RotateCcw, ChevronDown } from 'lucide-react';
7	
8	/**
9	 * Video-like timeline controls at the bottom of the screen
10	 * Features: play/pause, progress bar, chapter markers, chapter dropdown
11	 */
12	export function TimelineControls() {
13	    const tour = useTourController();
14	    const [isChapterDropdownOpen, setIsChapterDropdownOpen] = useState(false);
15	    const progressBarRef = useRef<HTMLDivElement>(null);
16	    const [isDragging, setIsDragging] = useState(false);
17	
18	    const {
19	        isActive,
20	        isPlaying,
21	        isPaused,
22	        isCompleted,
23	        isReducedMotion,
24	        progress,
25	        currentStep,
26	        currentStepIndex,
27	        totalSteps,
28	        currentChapter,
29	        chapters,
30	        totalDurationMs,
31	    } = tour;
32	
33	    // Handle progress bar click/drag
34	    const handleProgressInteraction = useCallback((e: React.MouseEvent | MouseEvent) => {
35	        if (!progressBarRef.current) return;
36	
37	        const rect = progressBarRef.current.getBoundingClientRect();
38	        const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
39	        const newProgress = x / rect.width;
40	        tour.seekTo(newProgress);
41	    }, [tour.seekTo]);
42	
43	    const handleMouseDown = (e: React.MouseEvent) => {
44	        setIsDragging(true);
45	        handleProgressInteraction(e);
46	
47	        const handleMouseMove = (e: MouseEvent) => {
48	            handleProgressInteraction(e);
49	        };
50	
51	        const handleMouseUp = () => {
52	            setIsDragging(false);
53	            window.removeEventListener('mousemove', handleMouseMove);
54	            window.removeEventListener('mouseup', handleMouseUp);
55	        };
56	
57	        window.addEventListener('mousemove', handleMouseMove);
58	        window.addEventListener('mouseup', handleMouseUp);
59	    };
60	
61	    // Format time display
62	    const formatTime = (ms: number) => {
63	        const seconds = Math.floor(ms / 1000);
64	        const minutes = Math.floor(seconds / 60);
65	        const remainingSeconds = seconds % 60;
66	        return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
67	    };
68	
69	    const currentTimeMs = progress * totalDurationMs;
70	    const elapsedTime = formatTime(currentTimeMs);
71	    const totalTime = formatTime(totalDurationMs);
72	
73	    if (!isActive) return null;
74	
75	    return (
76	        <AnimatePresence>
77	            {isActive && (
78	                <motion.div
79	                    className="fixed bottom-0 left-0 right-0 z-[10002] px-4 pb-4"
80	                    initial={{ opacity: 0, y: 20 }}
81	                    animate={{ opacity: 1, y: 0 }}
82	                    exit={{ opacity: 0, y: 20 }}
83	                    transition={{ duration: isReducedMotion ? 0.1 : 0.4 }}
84	                >
85	                    {/* Main controls container */}
86	                    <div
87	                        className="max-w-4xl mx-auto rounded-2xl overflow-hidden"
88	                        style={{
89	                            background: 'linear-gradient(135deg, rgba(10, 10, 15, 0.95) 0%, rgba(20, 20, 30, 0.95) 100%)',
90	                            backdropFilter: 'blur(20px)',
91	                            border: '1px solid rgba(255, 255, 255, 0.1)',
92	                            boxShadow: '0 -8px 32px rgba(0, 0, 0, 0.4)',
93	                        }}
94	                    >
95	                        {/* Progress bar with chapter markers */}
96	                        <div
97	                            ref={progressBarRef}
98	                            className="relative h-2 bg-white/10 cursor-pointer group"
99	                            onMouseDown={handleMouseDown}
100	                        >
101	                            {/* Chapter markers */}
102	                            {chapters.map((chapter, i) => {
103	                                const chapterStart = tour.config?.steps
104	                                    .slice(0, chapter.startStepIndex)
105	                                    .reduce((acc, s) => acc + s.durationMs, 0) ?? 0;
106	                                const position = (chapterStart / totalDurationMs) * 100;
107	
108	                                return (
109	                                    <div
110	                                        key={chapter.id}
111	                                        className="absolute top-0 bottom-0 w-0.5 bg-white/30"
112	                                        style={{ left: `${position}%` }}
113	                                        title={chapter.title}
114	                                    />
115	                                );
116	                            })}
117	
118	                            {/* Progress fill */}
119	                            <motion.div
120	                                className="absolute top-0 left-0 h-full bg-gradient-to-r from-amber-400 to-amber-500"
121	                                style={{ width: `${progress * 100}%` }}
122	                                transition={{ duration: isDragging ? 0 : 0.1 }}
123	                            />
124	
125	                            {/* Playhead */}
126	                            <motion.div
127	                                className="absolute top-1/2 -translate-y-1/2 w-4 h-4 bg-amber-400 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
128	                                style={{ left: `calc(${progress * 100}% - 8px)` }}
129	                            />
130	                        </div>
131	
132	                        {/* Controls row */}
133	                        <div className="px-4 py-3 flex items-center justify-between gap-4">
134	                            {/* Left: Time display */}
135	                            <div className="flex items-center gap-2 min-w-[100px]">
136	                                <span className="text-xs font-mono text-white/60">{elapsedTime}</span>
137	                                <span className="text-xs text-white/30">/</span>
138	                                <span className="text-xs font-mono text-white/40">{totalTime}</span>
139	                            </div>
140	
141	                            {/* Center: Playback controls */}
142	                            <div className="flex items-center gap-2">
143	                                {/* Previous */}
144	                                <button
145	                                    onClick={() => tour.prev()}
146	                                    className="p-2 rounded-lg text-white/60 hover:text-white hover:bg-white/10 transition-colors"
147	                                    aria-label="Previous step"
148	                                    disabled={currentStepIndex === 0}
149	                                >
150	                                    <SkipBack size={18} />
151	                                </button>
152	
153	                                {/* Play/Pause/Replay */}
154	                                {isCompleted ? (
155	                                    <button
156	                                        onClick={() => tour.goToStep(0)}
157	                                        className="p-3 rounded-full bg-amber-500 hover:bg-amber-400 text-black transition-colors"
158	                                        aria-label="Replay tour"
159	                                    >
160	                                        <RotateCcw size={20} />
161	                                    </button>
162	                                ) : (
163	                                    <button
164	                                        onClick={() => tour.togglePlayPause()}
165	                                        className="p-3 rounded-full bg-amber-500 hover:bg-amber-400 text-black transition-colors"
166	                                        aria-label={isPlaying ? 'Pause' : 'Play'}
167	                                    >
168	                                        {isPlaying ? <Pause size={20} /> : <Play size={20} className="ml-0.5" />}
169	                                    </button>
170	                                )}
171	
172	                                {/* Next */}
173	                                <button
174	                                    onClick={() => tour.next()}
175	                                    className="p-2 rounded-lg text-white/60 hover:text-white hover:bg-white/10 transition-colors"
176	                                    aria-label="Next step"
177	                                    disabled={currentStepIndex === totalSteps - 1}
178	                                >
179	                                    <SkipForward size={18} />
180	                                </button>
181	                            </div>
182	
183	                            {/* Right: Chapter dropdown and close */}
184	                            <div className="flex items-center gap-2 min-w-[100px] justify-end">
185	                                {/* Chapter dropdown */}
186	                                <div className="relative">
187	                                    <button
188	                                        onClick={() => setIsChapterDropdownOpen(!isChapterDropdownOpen)}
189	                                        className="flex items-center gap-1 px-2 py-1 rounded-lg text-xs font-medium text-white/60 hover:text-white hover:bg-white/10 transition-colors"
190	                                    >
191	                                        <span className="truncate max-w-[80px]">{currentChapter?.title ?? 'Chapters'}</span>
192	                                        <ChevronDown size={14} className={`transition-transform ${isChapterDropdownOpen ? 'rotate-180' : ''}`} />
193	                                    </button>
194	
195	                                    <AnimatePresence>
196	                                        {isChapterDropdownOpen && (
197	                                            <motion.div
198	                                                className="absolute bottom-full right-0 mb-2 py-1 rounded-lg overflow-hidden min-w-[140px]"
199	                                                style={{
200	                                                    background: 'rgba(20, 20, 30, 0.98)',
201	                                                    border: '1px solid rgba(255, 255, 255, 0.1)',
202	                                                    boxShadow: '0 -4px 20px rgba(0, 0, 0, 0.3)',
203	                                                }}
204	                                                initial={{ opacity: 0, y: 10 }}
205	                                                animate={{ opacity: 1, y: 0 }}
206	                                                exit={{ opacity: 0, y: 10 }}
207	                                            >
208	                                                {chapters.map((chapter) => (
209	                                                    <button
210	                                                        key={chapter.id}
211	                                                        onClick={() => {
212	                                                            tour.goToChapter(chapter.id);
213	                                                            setIsChapterDropdownOpen(false);
214	                                                        }}
215	                                                        className={`w-full px-3 py-2 text-left text-xs transition-colors ${currentChapter?.id === chapter.id
216	                                                                ? 'text-amber-400 bg-amber-400/10'
217	                                                                : 'text-white/60 hover:text-white hover:bg-white/10'
218	                                                            }`}
219	                                                    >
220	                                                        {chapter.title}
221	                                                    </button>
222	                                                ))}
223	                                            </motion.div>
224	                                        )}
225	                                    </AnimatePresence>
226	                                </div>
227	
228	                                {/* Close button */}
229	                                <button
230	                                    onClick={() => tour.exit()}
231	                                    className="p-2 rounded-lg text-white/60 hover:text-white hover:bg-white/10 transition-colors"
232	                                    aria-label="Exit tour"
233	                                >
234	                                    <X size={18} />
235	                                </button>
236	                            </div>
237	                        </div>
238	
239	                        {/* Step indicator */}
240	                        <div className="px-4 pb-3 flex items-center justify-center gap-1">
241	                            {Array.from({ length: totalSteps }).map((_, i) => (
242	                                <button
243	                                    key={i}
244	                                    onClick={() => tour.goToStep(i)}
245	                                    className={`w-1.5 h-1.5 rounded-full transition-all ${i === currentStepIndex
246	                                            ? 'w-4 bg-amber-400'
247	                                            : i < currentStepIndex
248	                                                ? 'bg-amber-400/50'
