                    }}
                    animate={{
                        y: [0, -30, 0],
                        x: [0, i % 2 === 0 ? 20 : -20, 0],
                        opacity: [0.2, 0.6, 0.2],
                    }}
                    transition={{
                        duration: 4 + i * 0.5,
                        repeat: Infinity,
                        delay: i * 0.3,
                        ease: "easeInOut",
                    }}
                />
            ))}
        </section>
    );
}
