import type { Metadata } from "next";
import { JetBrains_Mono, Space_Grotesk } from "next/font/google";
import "./globals.css";

import ResumeDownload from "@/components/ResumeDownload";
import SmoothScroll from "@/components/SmoothScroll";

import { TerminalProvider } from "@/context/TerminalContext";
import GlobalBackground from "@/components/GlobalBackground";
import { TourWrapper } from "@/components/Tour";


const jetbrainsMono = JetBrains_Mono({
  subsets: ["latin"],
  variable: "--font-jetbrains-mono",
});

const spaceGrotesk = Space_Grotesk({
  subsets: ["latin"],
  variable: "--font-space-grotesk",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Roshan Shah — Finance + AI",
  description: "Economics + Data Science student at UChicago. PE analyst at Blue Oak Group. Building at the intersection of finance, AI, and technical systems.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className="dark" suppressHydrationWarning>
      <body className={`${spaceGrotesk.variable} ${jetbrainsMono.variable} antialiased bg-background-dark text-text-main font-sans selection:bg-primary/30 selection:text-white`}>
        <TerminalProvider>
          <SmoothScroll>
            <TourWrapper>
              <GlobalBackground />
              {children}
              <ResumeDownload />
            </TourWrapper>
          </SmoothScroll>
        </TerminalProvider>
      </body>
    </html>
  );
}

