10	type Point = { x: number; y: number };
11	
12	/**
13	 * Cubic Bezier curve interpolation (4 control points)
14	 * Returns point on curve at time t (0-1)
15	 */
16	function cubicBezier(p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point {
17	    const u = 1 - t;
18	    const tt = t * t;
19	    const uu = u * u;
20	    const uuu = uu * u;
21	    const ttt = tt * t;
22	
23	    return {
24	        x: uuu * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + ttt * p3.x,
25	        y: uuu * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + ttt * p3.y,
26	    };
27	}
28	
29	/**
30	 * Calculate tangent angle on cubic bezier at time t
31	 */
32	function cubicBezierTangent(p0: Point, p1: Point, p2: Point, p3: Point, t: number): number {
33	    const u = 1 - t;
34	    // First derivative of cubic bezier
35	    const dx = 3 * u * u * (p1.x - p0.x) + 6 * u * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x);
36	    const dy = 3 * u * u * (p1.y - p0.y) + 6 * u * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y);
37	    return Math.atan2(dy, dx) * (180 / Math.PI);
38	}
