        const dy = endPoint.y - startPoint.y;
        const approachAngle = Math.atan2(dy, dx) + (Math.random() - 0.5) * 1.2; // ±0.6 rad variance
        const approachDistance = 100 + Math.random() * 80;
        const p2: Point = {
            x: endPoint.x - Math.cos(approachAngle) * approachDistance,
