            x: startPoint.x + Math.cos(angleRad) * entryDistance,
            y: startPoint.y + Math.sin(angleRad) * entryDistance,
        };

        // End point: random location
        const endPoint = randomPoint();

        // P2: Control point near end, influences approach angle
