import type { Metadata } from "next";
import { JetBrains_Mono, Space_Grotesk } from "next/font/google";
import "./globals.css";

import ResumeDownload from "@/components/ResumeDownload";
import SmoothScroll from "@/components/SmoothScroll";

import { TerminalProvider } from "@/context/TerminalContext";
import GlobalBackground from "@/components/GlobalBackground";
import { TourWrapper } from "@/components/Tour";


const jetbrainsMono = JetBrains_Mono({
  subsets: ["latin"],
  variable: "--font-jetbrains-mono",
});

const spaceGrotesk = Space_Grotesk({
  subsets: ["latin"],
  variable: "--font-space-grotesk",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Roshan Shah — Finance + AI",
  description: "Economics student at UChicago building across finance, AI, aerospace, and simulation software. Summer analyst at Blue Oak Group. Interested in robotics, drone tech, and trading.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className="dark" suppressHydrationWarning>
      <body className={`${spaceGrotesk.variable} ${jetbrainsMono.variable} antialiased bg-background-dark text-text-main font-sans selection:bg-primary/30 selection:text-white`}>
        <TerminalProvider>
          <SmoothScroll>
            <TourWrapper>
              <GlobalBackground />
              {children}
              <ResumeDownload />
            </TourWrapper>
          </SmoothScroll>
        </TerminalProvider>
      </body>
    </html>
  );
}

"use client";

import { motion, useScroll, useTransform } from "framer-motion";
import { useRef, useState, useEffect } from "react";
import ProfileImage3D from "./ProfileImage3D";

const education = [
    {
        school: "The University of Chicago",
        program: "BA Economics + Data Science spec",
        degree: "Minor: Entrepreneurship & Innovation (Sep 2026–2029)",
        details: "Formerly UNC Kenan-Flagler Business School (4.0 GPA, Honors Carolina)"
    },
    {
        school: "The Lawrenceville School",
        program: "High School (GPA 3.92/4.00)",
        details: "Herman Hollerith Prize, Cum Laude Society, McClellan Society"
    }
];

const skills = {
    languages: ["Python", "Swift", "JS/TS", "SQL"],
    skills: [
        "DCF / Comps",
        "Equity Research",
        "Venture Diligence",
        "AI / Technical Systems",
        "PCB",
        "KiCad",
        "SolidWorks",
        "Fusion360",
        "soldering"
    ],
    interests: ["Robotics", "Drone Tech", "Trading", "Poker", "Football", "Traveling", "Reading", "AI governance", "Tabla", "Photography"]
};

export default function AboutSection() {
    const [isMounted, setIsMounted] = useState(false);
    useEffect(() => {
        const timer = window.setTimeout(() => setIsMounted(true), 0);
        return () => window.clearTimeout(timer);
    }, []);
    const sectionRef = useRef<HTMLDivElement>(null);
    const { scrollYProgress } = useScroll({
        target: sectionRef,
        offset: ["start end", "end start"]
    });

    const textX = useTransform(scrollYProgress, [0, 0.5], [-50, 0]);
    const textOpacity = useTransform(scrollYProgress, [0, 0.3], [0, 1]);
    const imageScale = useTransform(scrollYProgress, [0, 0.5], [0.8, 1]);

    return (
        <section id="about" ref={sectionRef} data-tour="about" className="py-16 px-4 relative">
            <div className="section-container">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
                    {/* Left: Profile Image */}
                    <motion.div
                        className="lg:col-span-4"
                        style={isMounted ? { scale: imageScale, opacity: textOpacity } : {}}
                    >
                        <ProfileImage3D />
                    </motion.div>

                    {/* Right: Bio Content */}
                    <motion.div
                        className="lg:col-span-8 space-y-8"
                        style={isMounted ? { x: textX, opacity: textOpacity } : {}}
                    >
                        {/* Bio */}
                        <div>
                            <p className="text-lg md:text-xl text-gray-300 leading-relaxed">
                                Hey, I'm <span className="text-amber-400 font-bold">Roshan</span>, a sophomore at UChicago studying economics. Most of my time right now goes to projects in aerospace and simulation software, and to the technical side of investing as a summer analyst at Blue Oak Group, where I build AI tools that source and screen acquisition targets. Robotics, drone tech, and trading are the problems I keep coming back to, usually where finance, AI, and hardware run into each other.
                            </p>
                        </div>

                        {/* Education */}
                        <div data-tour="education" className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {education.map((edu, i) => (
                                <motion.div
                                    key={i}
                                    initial={{ opacity: 0, y: 20 }}
                                    whileInView={{ opacity: 1, y: 0 }}
                                    viewport={{ once: true }}
                                    transition={{ delay: i * 0.1 }}
                                    className="bg-white/[0.02] border border-white/10 rounded-lg p-4"
                                >
                                    <h4 className="text-sm font-bold text-white">{edu.school}</h4>
                                    <p className="text-xs text-cyan-400 font-mono mt-1">{edu.program}</p>
                                    <p className="text-xs text-white font-medium mt-2">{edu.degree}</p>
                                    {edu.details && <p className="text-xs text-gray-400 mt-1">{edu.details}</p>}
                                </motion.div>
                            ))}
                        </div>

                        {/* Skills Grid */}
                        <div data-tour="skills" className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {Object.entries(skills).map(([category, items], i) => (
                                <motion.div
                                    key={category}
                                    initial={{ opacity: 0, y: 20 }}
                                    whileInView={{ opacity: 1, y: 0 }}
                                    viewport={{ once: true }}
                                    transition={{ delay: i * 0.05 }}
                                    className="space-y-2"
                                >
                                    <h4 className="text-[10px] font-bold text-amber-400 uppercase tracking-wider">
                                        {category}
                                    </h4>
                                    <ul className="space-y-1">
                                        {items.map((item, j) => (
                                            <li key={j} className="text-xs text-gray-400 font-mono">{item}</li>
                                        ))}
                                    </ul>
                                </motion.div>
                            ))}
                        </div>

                    {/* Contact Links */}
                    <div className="flex flex-wrap gap-3">
                        <a
                            href="mailto:rashah@uchicago.edu"
                            className="flex items-center gap-2 px-4 py-2 bg-amber-500/20 border border-amber-500/30 rounded-lg hover:bg-amber-500/30 transition-all text-sm text-amber-400 font-medium"
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <rect x="2" y="4" width="20" height="16" rx="2" />
                                <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7" />
                            </svg>
                            UChicago Email
                        </a>
                        <a
                            href="mailto:roshah2007@gmail.com"
                            className="flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-lg hover:border-amber-500/50 hover:bg-white/10 transition-all text-sm text-white"
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <rect x="2" y="4" width="20" height="16" rx="2" />
                                <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7" />
                            </svg>
                            Gmail
                        </a>
                        <a
                            href="https://www.linkedin.com/in/roshan-shah11/"
                            target="_blank"
                            className="flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-lg hover:border-cyan-500/50 hover:bg-white/10 transition-all text-sm text-white"
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z" />
                                <rect x="2" y="9" width="4" height="12" />
                                <circle cx="4" cy="4" r="2" />
                            </svg>
                            LinkedIn
                        </a>
                        <a
                            href="https://github.com/roshanshah11"
                            target="_blank"
                            className="flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-lg hover:border-gray-500/50 hover:bg-white/10 transition-all text-sm text-white"
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <path d="M15 22v-4a4.8 4.8 0 0 0-1-3.5c3 0 6-2 6-5.5.08-1.25-.27-2.48-1-3.5.28-1.15.28-2.35 0-3.5 0 0-1 0-3 1.5-2.64-.5-5.36-.5-8 0C6 2 5 2 5 2c-.3 1.15-.3 2.35 0 3.5A5.403 5.403 0 0 0 4 9c0 3.5 3 5.5 6 5.5-.39.49-.68 1.05-.85 1.65-.17.6-.22 1.23-.15 1.85v4" />
                                <path d="M9 18c-4.51 2-5-2-7-2" />
                            </svg>
                            GitHub
                        </a>
                        <a
                            href="/roshan_shah_resume.pdf"
                            target="_blank"
                            className="flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-lg hover:border-amber-500/50 hover:bg-white/10 transition-all text-sm text-white"
                        >
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                                <polyline points="14 2 14 8 20 8" />
                                <line x1="16" y1="13" x2="8" y2="13" />
                                <line x1="16" y1="17" x2="8" y2="17" />
                            </svg>
                            Resume
                        </a>
                    </div>
                    </motion.div>
                </div>
            </div>
        </section>
    );
}

"use client";

import { motion, useScroll, useTransform } from "framer-motion";
import { useRef, useState, useEffect } from "react";
import TextReveal from "./TextReveal";
import { useLenis } from "./SmoothScroll";

export default function HeroSection() {
    const [isMounted, setIsMounted] = useState(false);
    useEffect(() => {
        const timer = window.setTimeout(() => setIsMounted(true), 0);
        return () => window.clearTimeout(timer);
    }, []);
    const sectionRef = useRef<HTMLDivElement>(null);
    const { scrollYProgress } = useScroll({
        target: sectionRef,
        offset: ["start start", "end start"]
    });

    const lenis = useLenis();

    useEffect(() => {
        if (!lenis) return;

        // Auto-scroll after animation completion
        const timer = setTimeout(() => {
            lenis.scrollTo("#about", {
                duration: 2.5,
                easing: (t: number) => 1 - Math.pow(1 - t, 3)
            });
        }, 2500);

        return () => clearTimeout(timer);
    }, [lenis]);

    const y = useTransform(scrollYProgress, [0, 1], [0, 200]);
    const opacity = useTransform(scrollYProgress, [0, 0.5], [1, 0]);
    const scale = useTransform(scrollYProgress, [0, 0.5], [1, 0.9]);

    return (
        <section
            ref={sectionRef}
            data-tour="hero"
            className="relative min-h-screen min-h-[100dvh] flex flex-col items-center justify-center overflow-hidden"
        >
            <motion.div
                className="text-center z-10"
                style={isMounted ? { y, opacity, scale } : {}}
            >
                {/* Main Name */}
                <div className="overflow-hidden">
                    <TextReveal
                        text="ROSHAN SHAH"
                        className="text-5xl sm:text-7xl md:text-8xl lg:text-9xl font-bold tracking-tighter"
                        delay={300}
                    />
                </div>

                {/* Subtitle */}
                <motion.div
                    initial={{ opacity: 0, y: 30 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 1, delay: 1.2 }}
                    className="mt-6"
                >
                    <div className="flex items-center justify-center gap-3">
                        <motion.div
                            className="h-px w-12 bg-gradient-to-r from-transparent to-amber-500"
                            initial={{ scaleX: 0 }}
                            animate={{ scaleX: 1 }}
                            transition={{ duration: 0.8, delay: 1.5 }}
                        />
                        <span className="text-sm md:text-base tracking-[0.3em] text-gray-400 font-mono">
                            FINANCE + AI
                        </span>
                        <motion.div
                            className="h-px w-12 bg-gradient-to-l from-transparent to-cyan-500"
                            initial={{ scaleX: 0 }}
                            animate={{ scaleX: 1 }}
                            transition={{ duration: 0.8, delay: 1.5 }}
                        />
                    </div>
                </motion.div>

                {/* Brief tagline */}
                <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 1, delay: 1.8 }}
                    className="mt-8 text-sm md:text-base text-gray-500 max-w-md mx-auto px-4"
                >
                    Building where finance, AI, and hardware meet, from public markets
                    to aerospace and simulation software.
                </motion.p>

                {/* Scroll indicator */}
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 1, delay: 2.2 }}
                    className="mt-16"
                >
                    <motion.div
                        animate={{ y: [0, 10, 0] }}
                        transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                        className="flex flex-col items-center gap-2"
                    >
                        <span className="text-xs text-gray-600 tracking-widest">SCROLL</span>
                        <div className="w-5 h-8 border border-gray-600 rounded-full flex justify-center pt-2">
                            <motion.div
                                animate={{ y: [0, 8, 0], opacity: [1, 0, 1] }}
                                transition={{ duration: 1.5, repeat: Infinity }}
                                className="w-1 h-1 bg-amber-500 rounded-full"
                            />
                        </div>
                    </motion.div>
                </motion.div>
            </motion.div>

            {/* Floating particles */}
            {[...Array(8)].map((_, i) => (
                <motion.div
                    key={i}
                    className="absolute w-1 h-1 rounded-full"
                    style={{
                        left: `${20 + (i * 10)}%`,
                        top: `${30 + (i % 3) * 20}%`,
                        background: i % 2 === 0 ? "#D4AF37" : "#00D9FF",
                        boxShadow: `0 0 ${6 + i}px ${i % 2 === 0 ? "#D4AF37" : "#00D9FF"}`,
                    }}
                    animate={{
                        y: [0, -30, 0],
                        x: [0, i % 2 === 0 ? 20 : -20, 0],
                        opacity: [0.2, 0.6, 0.2],
                    }}
                    transition={{
                        duration: 4 + i * 0.5,
                        repeat: Infinity,
                        delay: i * 0.3,
                        ease: "easeInOut",
                    }}
                />
            ))}
        </section>
    );
}

"use client";

import React from 'react';

const ResumeDownload = () => {
    return (
        <a
            href="/roshan_shah_resume.pdf"
            target="_blank"
            rel="noopener noreferrer"
            className="fixed top-6 right-6 z-40 group"
            aria-label="Download Resume"
        >
            <div className="relative flex items-center justify-center w-40 h-12 bg-background-dark border border-white/10 rounded-full shadow-lg overflow-hidden transition-all duration-300 group-hover:border-primary/50">

                {/* Icon */}
                <div className="absolute left-3 text-text-muted group-hover:text-primary transition-colors">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M21 15V19C21 19.5304 20.7893 20.0391 20.4142 20.4142C20.0391 20.7893 19.5304 21 19 21H5C4.46957 21 3.96086 20.7893 3.58579 20.4142C3.21071 20.0391 3 19.5304 3 19V15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        <path d="M7 10L12 15L17 10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        <path d="M12 15V3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                </div>

                {/* Text (Revealed on Hover) */}
                <span className="ml-8 text-sm font-mono font-bold text-primary opacity-100 transition-opacity duration-300 whitespace-nowrap">
                    GET RESUME
                </span>

                {/* Glow Effect */}
                <div className="absolute inset-0 rounded-full opacity-0 group-hover:opacity-20 bg-primary blur-md transition-opacity duration-300"></div>
            </div>
        </a>
    );
};

export default ResumeDownload;

