@import "tailwindcss";

@theme {
  --font-sans: var(--font-space-grotesk), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-jetbrains-mono), monospace;
  --font-display: var(--font-space-grotesk), ui-sans-serif, system-ui, sans-serif;

  /* Sleek Modern Palette */
  --color-background-dark: #09090b;
  /* Zinc 950 */
  --color-background-black: #09090b;
  /* Replaced true black with deep charcoal */
  --color-background-light: #18181b;
  /* Zinc 900 */

  /* Sophisticated Accents */
  --color-primary: #3b82f6;
  --color-primary-glow: rgba(59, 130, 246, 0.3);

  --color-accent-cyan: #00D9FF;
  --color-accent-gold: #D4AF37;
  --color-accent-blue: #3b82f6;
  --color-destructive: #ef4444;

  --color-text-main: #ededed;
  --color-text-muted: #71717a;

  /* Glassmorphism Refined */
  --color-glass-bg: rgba(255, 255, 255, 0.02);
  --color-glass-border: rgba(255, 255, 255, 0.06);
}

@layer base {
  html {
    scroll-behavior: smooth;
  }

  body {
    @apply text-text-main font-sans min-h-screen flex flex-col antialiased overflow-x-hidden;
    background: transparent;
  }

  .bg-background-black {
    background-color: var(--color-background-black);
  }
}

@layer utilities {
  .glass-panel {
    @apply bg-glass-bg border border-glass-border backdrop-blur-xl rounded-2xl shadow-2xl transition-all duration-300;
  }

  .text-glow {
    text-shadow: 0 0 20px var(--color-primary-glow);
  }

  .text-gradient {
    @apply bg-clip-text text-transparent bg-gradient-to-r from-white via-gray-200 to-gray-400;
  }

  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes scan {
  0% {
    top: 0%;
    opacity: 0;
  }

  10% {
    opacity: 1;
  }

  90% {
    opacity: 1;
  }

  100% {
    top: 100%;
    opacity: 0;
  }
}

@keyframes blink {

  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0;
  }
}

.animate-fade-in {
  animation: fadeIn 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.animate-slide-up {
  animation: slideUp 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.animate-scale-in {
  animation: scaleIn 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.animate-blink {
  animation: blink 1s step-end infinite;
}

.delay-100 {
  animation-delay: 100ms;
}

.delay-200 {
  animation-delay: 200ms;
}

.delay-300 {
  animation-delay: 300ms;
}

.section-container {
  @apply max-w-[90rem] mx-auto;
